import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import hmac

app = Flask(__name__)
app.config['DATABASE'] = os.environ.get('DB_PATH', '/data/app.db')
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', 'dev-secret-key-change-me')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = get_db()
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, email TEXT, role TEXT, password_hash TEXT)')
    db.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, user_id INTEGER, details TEXT, ts DATETIME DEFAULT CURRENT_TIMESTAMP)')
    db.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, title TEXT, content TEXT, owner_id INTEGER, classification TEXT)')
    db.commit()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'unauthorized'}), 401
        token = auth_header[7:]
        # Token format: user_id:timestamp:signature
        parts = token.split(':')
        if len(parts) != 3:
            return jsonify({'error': 'invalid token'}), 401
        user_id, ts, sig = parts
        expected = hmac.new(app.config['SECRET_KEY'].encode(), f"{user_id}:{ts}".encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        g.current_user_id = int(user_id)
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/search', methods=['GET'])
@require_auth
def search_documents():
    """Search documents with filtering. Supports field-based search."""
    search_field = request.args.get('field', 'title')
    search_value = request.args.get('q', '')
    classification = request.args.get('classification', 'public')

    # Validate classification parameter
    allowed_classifications = ['public', 'internal', 'confidential']
    if classification not in allowed_classifications:
        return jsonify({'error': 'invalid classification'}), 400

    # Build query - field is used for column selection
    # Note: search_value is parameterized but field is not
    query = f"SELECT id, title, classification FROM documents WHERE {search_field} LIKE ? AND classification = ? AND owner_id = ?"

    db = get_db()
    try:
        results = db.execute(query, (f'%{search_value}%', classification, g.current_user_id)).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        # Log the error for debugging
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ? AND owner_id = ?', (doc_id, g.current_user_id)).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
@require_auth
def create_document():
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400
    db = get_db()
    db.execute('INSERT INTO documents (title, content, owner_id, classification) VALUES (?, ?, ?, ?)',
               (data['title'], data.get('content', ''), g.current_user_id, data.get('classification', 'public')))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    with app.app_context():
        init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('DEBUG', 'false').lower() == 'true')
